import { GameData } from '../../Core/Data/GameData';
import type { System } from '../../Engine/System';
import type { World } from '../../Engine/World';
import { Plane } from '../Entity/Plane';

export type SpawnSide = 'top' | 'left' | 'right';

export class EnemySpawnSystem implements System {

    private _spawnTimer = 0;
    private _spawnInterval = 1.5;    // 每 1.5 秒生成一个敌机


    onTick(world: World, dt: number): void {
        this._spawnTimer += dt;
        while (this._spawnTimer >= this._spawnInterval) {
            this._spawnTimer -= this._spawnInterval;
            this._spawnOneEnemy(world, this._pickSide());
        }
    }

    /** 60% 从顶部，20% 从左，20% 从右 */
    private _pickSide(): SpawnSide {
        const r = Math.random();
        if (r < 0.6) return 'top';
        if (r < 0.8) return 'left';
        return 'right';
    }

    private _spawnOneEnemy(world: World, side: SpawnSide): void {
        const plane = new Plane('enemy');

        const halfW = GameData.viewW / 2;
        const halfH = GameData.viewH / 2;

        if (side === 'top') {
            plane.x = -halfW + Math.random() * GameData.viewW;
            plane.y = halfH + 30;
            plane.moveDirX = 0;
            plane.moveDirY = -1;
            plane.movePattern = Math.random() < 0.5 ? 'straight' : 'sine';
        } else if (side === 'left') {
            plane.x = -halfW - 30;
            plane.y = -halfH * 0.6 + Math.random() * halfH * 0.6;
            plane.moveDirX = 1;
            plane.moveDirY = 0;
            plane.movePattern = 'straight';
        } else {
            plane.x = halfW + 30;
            plane.y = -halfH * 0.6 + Math.random() * halfH * 0.6;
            plane.moveDirX = -1;
            plane.moveDirY = 0;
            plane.movePattern = 'straight';
        }

        plane.originX = plane.x;
        plane.originY = plane.y;
        plane.hp = 30;
        plane.maxHp = 30;
        plane.moveSpeed = 100;
        plane.collisionRadius = 20;

        plane.weapons.push({
            fireInterval: 2.0,
            cooldownTimer: Math.random() * 2.0,   // 随机初始冷却，避免所有敌机同时开火
            bulletType: 'yellow',
            bulletSpeed: 200,
            bulletDamage: 8,
            fireDirX: 0,
            fireDirY: -1,          // 向下
            enabled: true,
        });
        world.add(plane);
    }
}


